import { useState } from 'react';
import './editor.css';
import Editor from "@monaco-editor/react";
import Axios from 'axios';
function Editor1() {
    // State variable to users source code
    const [userCode, setUserCode] = useState(``);
    
    // State variable to set editors default language
    const [userLang, setUserLang] = useState("python");
    // State variable to set users output
    const [userOutput, setUserOutput] = useState("");
    // while fetching data
    const [loading, setLoading] = useState(false);
    // Function to call the compile endpoint
    function compile() {
        setLoading(true);
        if (userCode === ``) {
            return
        }

        // Post request to compile endpoint
        Axios.post(`http://localhost:5000/run`, {
            code: userCode,
            language: userLang,
          
        }).then((res) => {
            setUserOutput(res.data.stdout || res.data.stderr);
        }).then(() => {
            setLoading(false);
        }).catch((err) => {
            console.error(err);
            setUserOutput("Error: " + (err.response ? err.response.data.error : err.message));
            setLoading(false);
        });
    }
    // Function to clear the output screen
    function clearOutput() {
        setUserOutput("");
    }

    return (
        <div className="container">
           {/* <Navbar
                userLang={userLang} setUserLang={setUserLang}
                userTheme={userTheme} setUserTheme={setUserTheme}
                fontSize={fontSize} setFontSize={setFontSize}
            /> */}

   
                <div className='headChoicePannel'>
                        <h2 id='headChoice'>Language</h2>
                        <select  className="selectLan" value={userLang} onChange={(e=>setUserLang(e.target.value))}>
                        <option value="java">Java</option>
                        <option value="python">python</option>
                        <option value="c">C</option>
                        <option value="cpp">C++</option>
                        </select>
                </div>
        <div className="main">
            <div className="left-container">
                <button className="run-btn" onClick={() => compile()}>
                    Run Code
                </button>
    
                <Editor
                        height="100%"
                        width="95%"
                        font-size="40"
                        border="2px solid pink"
                        theme="vs-dark"
                        language={userLang}
                        defaultLanguage="python"
                        defaultValue="# Enter your code here"
                        onChange={(value) => { setUserCode(value) }}
                    />
                   
            </div>
                
                    <div className='outputSection'>
                    <h2 id="output_heading">Output:</h2>
                    {loading ? (
                        <div className="spinner-box">
                        </div>
                    ) : (
                        <div className="output-box">
                            <pre id="outputline">{userOutput}</pre>
                            <button onClick={() => { clearOutput() }}
                                className="clear-btn">
                                Clear
                            </button>
                        </div>
                    )}
                    </div>
                </div>
            </div>
    );
}

export default Editor1;
